<?php require_once __DIR__.'/functions.php'; require_once __DIR__.'/app_init.php'; start_app('Mi perfil','perfil'); $pdo=dogvive_db();$uid=dogvive_user_id();$q=$pdo->prepare('SELECT * FROM usuario WHERE id_usuario=?');$q->execute([$uid]);$u=$q->fetch();$name=trim(($u['Nombre']??'').' '.($u['Apellido']??''));$count=$pdo->prepare('SELECT COUNT(*) FROM mascota WHERE id_usuario=?');$count->execute([$uid]);$pets=(int)$count->fetchColumn();$success=dogvive_flash('success');page_wrap_start('Mi perfil','Consulta y administra tu información personal.');if($success)echo '<div class="notice">'.e($success).'</div>'; ?>
<div class="detail-grid"><div class="card" style="text-align:center"><div class="avatar"><?= e(mb_strtoupper(mb_substr($name?:'U',0,1))) ?></div><h2 style="margin-top:15px"><?= e($name) ?></h2><p class="muted"><?= e(current_role()) ?> · <?= e((string)($u['Ciudad']??$u['Direccion']??'')) ?></p><?php if(current_role()==='Entrenador'): ?><span class="badge"><?= e((string)($u['Estado_verificacion']??'Pendiente')) ?> de verificación</span><?php endif; ?></div><div class="card"><div style="display:flex;justify-content:space-between;align-items:center;gap:10px"><h3>Información personal</h3><?= btn('Editar datos',page_url('editar-perfil'),'btn-secondary') ?></div><div class="grid grid-2" style="margin-top:16px"><?php foreach(['Documento'=>'Documento','Usuario'=>'Usuario','Correo'=>'Correo','Telefono'=>'Teléfono','Ciudad'=>'Ciudad','Especialidad'=>'Especialidad'] as $key=>$label): if(($u[$key]??'')!==''): ?><div class="card"><small class="muted"><?= e($label) ?></small><strong><?= e((string)$u[$key]) ?></strong></div><?php endif; endforeach; ?></div><h3 style="margin-top:24px">Resumen</h3><div class="grid grid-2"><div class="card"><strong><?= $pets ?></strong><small class="muted">Mascotas registradas</small></div><div class="card"><strong><?= e(current_role()) ?></strong><small class="muted">Tipo de cuenta</small></div></div></div></div><?php page_wrap_end();end_app();
